#!/usr/bin/env node
/* Build the release bundle: sgm-<release>.zip (release from ./VERSION, so v1, v2, ...).
 *
 *     node tools/make_bundle.mjs            # -> sgm-v1.zip
 *     node tools/make_bundle.mjs --dry-run  # list what would go in
 *
 * Contents: all source (src/, web/, desktop/, tools/), the model bundles, the task-specific data,
 * samples, logs and the docs. Excluded on purpose: .pt training checkpoints (large, resumable
 * anyway), node_modules, .venv, downloads/ and desktop build output (all regenerated by the tools
 * in this archive). The zip is written by web/zip.js, so the archive format is the one this project
 * ships and tests.
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { buildZip, versionedName } from '../web/zip.js';
import { PROJECT_ROOT, readRelease } from '../web/server.js';

const root = PROJECT_ROOT;
const release = await readRelease(root);
const out = join(root, versionedName('sgm', release));

const SKIP_DIRS = new Set([
  '.git', '.venv', 'node_modules', '__pycache__', 'downloads', 'dist', 'build', '.cache',
  'checkpoints', 'checkpoints_code', 'checkpoints_demo', 'checkpoints_demo2', 'checkpoints_int4',
  'checkpoints_10m', 'checkpoints_100m', 'checkpoints_smoke',
]);
const SKIP_EXT = /\.(pt|pyc|log\.csv)$/i;
const KEEP_LOGS = /(^|\/)(logs|samples)\//;

function walk(dir, files = [], base = root) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name) || entry.name.startsWith('.')) continue;
      walk(path, files, base);
    } else if (entry.isFile()) {
      const rel = relative(base, path).replace(/\\/g, '/');
      if (SKIP_EXT.test(entry.name) && !KEEP_LOGS.test(rel)) continue;
      if (/\.zip$/i.test(entry.name) && /^image-ai-/.test(entry.name)) continue;   // superseded bundles
      files.push(rel);
    }
  }
  return files;
}

const names = walk(root).sort();
if (process.argv.includes('--dry-run')) {
  let total = 0;
  for (const n of names) {
    const size = statSync(join(root, n)).size;
    total += size;
    console.log(`${String((size / 1024).toFixed(1)).padStart(9)} kB  ${n}`);
  }
  console.log(`${names.length} files, ${(total / 1048576).toFixed(2)} MiB before compression`);
  process.exit(0);
}

const files = names.map(name => ({ name, data: () => new Uint8Array(readFileSync(join(root, name))) }));
files.push({
  name: 'BUNDLE.txt',
  data: `SGM (Small Generative Model) ${release}\r\nbuilt ${new Date().toISOString()}\r\n` +
    `${names.length} files\r\n\r\n` +
    `Start here\r\n  1. node web/server.js        -> http://localhost:3000\r\n` +
    `  2. the model picker loads a bundle on your first message\r\n` +
    `  3. desktop app:        cd desktop && npm install && npm start\r\n` +
    `  4. build the .exe:     node tools/build_desktop.mjs --platform=win32\r\n` +
    `  5. model downloads:    node tools/make_downloads.mjs\r\n` +
    `  6. every check:        npm test\r\n\r\n` +
    `Training checkpoints (*.pt) are not included: retrain with train.cmd, or copy the bundle folder\r\n` +
    `you want (web_model/, web_model_code/, web_model_int4/) next to web/.\r\n`,
});

const t0 = Date.now();
const { bytes, entries } = await buildZip(files);
writeFileSync(out, bytes);
console.log(`wrote ${out}`);
console.log(`${entries.length} files, ${(bytes.length / 1048576).toFixed(2)} MiB, ` +
  `${((Date.now() - t0) / 1000).toFixed(1)}s`);
